(6208591, 917344, 96751, '<td valign="top">Right time, right place images are so breathtaking.  Worth the drench, I''d say.</td>', 'Right time, right place images are so breathtaking.  Worth the drench, I''d say.', '2010-11-02 12:21:30.000000', NULL, 1),
(6208592, 917243, 96751, '<td valign="top">LOVE this image.  Powerful, mysterious, intimidating.</td>', 'LOVE this image.  Powerful, mysterious, intimidating.', '2010-11-02 12:21:59.000000', NULL, 1),
(6208594, 917507, 96751, '<td valign="top">An image after my own heart.  Just wonderful.  I love that the figure seems to be moving towards the brightness, and we are chasing him, to not be lost in the dark, alone.</td>', 'An image after my own heart.  Just wonderful.  I love that the figure seems to be moving towards the brightness, and we are chasing him, to not be lost in the dark, alone.', '2010-11-02 12:23:49.000000', NULL, 1),
(6208595, 916954, 96751, '<td valign="top">Such a beautiful abstract.  The colors are delicious.</td>', 'Such a beautiful abstract.  The colors are delicious.', '2010-11-02 12:24:33.000000', NULL, 1),
