(6208600, 917475, 96751, '<td valign="top">So lovely.  That chandelier is so improbable!!  A great touch, but would have liked it just a tish more to the right so it doesn''t crowd her (and the tiara) so much.</td>', 'So lovely.  That chandelier is so improbable!!  A great touch, but would have liked it just a tish more to the right so it doesn''t crowd her (and the tiara) so much.', '2010-11-02 12:28:19.000000', NULL, 1),
(6208601, 917487, 96751, '<td valign="top">Lovely and pastoral.</td>', 'Lovely and pastoral.', '2010-11-02 12:29:06.000000', NULL, 1),
(6208602, 917256, 96751, '<td valign="top">Very sick.  Weird.  Compelling.  Does she have cramps?</td>', 'Very sick.  Weird.  Compelling.  Does she have cramps?', '2010-11-02 12:29:34.000000', NULL, 1),
