(6211827, 916296, 19944, '<td valign="top">Very "On Golden Pond"ish.  Maybe a little dark for my taste, but still nice</td>', 'Very "On Golden Pond"ish.  Maybe a little dark for my taste, but still nice', '2010-11-04 15:59:14.000000', NULL, 1),
(6211831, 917234, 19944, '<td valign="top">This seems kind of flat</td>', 'This seems kind of flat', '2010-11-04 15:59:38.000000', NULL, 1),
