(6211842, 917398, 19944, '<td valign="top">The river is a little dark.  Boosting that would help this image tremendously.</td>', 'The river is a little dark.  Boosting that would help this image tremendously.', '2010-11-04 16:03:53.000000', NULL, 1),
(6211874, 915409, 19944, '<td valign="top">Something about this just grabs me.  Maybe the limited number of colors.  Or maybe it''s just that I like running.  Who knows.  I love it. 9</td>', 'Something about this just grabs me.  Maybe the limited number of colors.  Or maybe it''s just that I like running.  Who knows.  I love it. 9', '2010-11-04 16:25:29.000000', NULL, 1),
(6211903, 917023, 1024, '<td valign="top">I hate to admit that I am one of those 3 second voters... but this image had me staring for over a minute.  There is so much beauty here.  IO am sure I will revisit often.  Wonderful capture!</td>', 'I hate to admit that I am one of those 3 second voters... but this image had me staring for over a minute.  There is so much beauty here.  IO am sure I will revisit often.  Wonderful capture!', '2010-11-04 16:38:28.000000', NULL, 1),
