(6211918, 916269, 1024, '<td valign="top">Now there is a look of determination!</td>', 'Now there is a look of determination!', '2010-11-04 16:42:25.000000', NULL, 1),
(6211932, 917449, 1024, '<td valign="top">This makes me smile but I am not sure why.</td>', 'This makes me smile but I am not sure why.', '2010-11-04 16:48:37.000000', NULL, 1),
