(6214169, 912533, 108857, '<td valign="top">thats one heck of a catch!  Truely impressive.</td>', 'thats one heck of a catch!  Truely impressive.', '2010-11-06 23:14:03.000000', NULL, 1),
(6214171, 917290, 108857, '<td valign="top">I like the B&amp;W.  Nice image.</td>', 'I like the B&W.  Nice image.', '2010-11-06 23:17:21.000000', NULL, 1),
(6214172, 916955, 108857, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2010-11-06 23:18:49.000000', NULL, 1),
(6214174, 917262, 108857, '<td valign="top">I like the reflection, too bad the image seems to lack extream sharpness.  It might even be better if it had been out of focus and a bit more abstract.</td>', 'I like the reflection, too bad the image seems to lack extream sharpness.  It might even be better if it had been out of focus and a bit more abstract.', '2010-11-06 23:21:46.000000', NULL, 1);
