(6215216, 917324, 76335, '<td valign="top">A beautiful fairy tale. Nicely done.</td>', 'A beautiful fairy tale. Nicely done.', '2010-11-07 19:01:10.000000', NULL, 1),
(6215219, 917085, 76335, '<td valign="top">That''s one fiery rainbow! Very bold. Only quibble would be that the noise reduction has left some nasty visible crosshatching. Seven anyway.</td>', 'That''s one fiery rainbow! Very bold. Only quibble would be that the noise reduction has left some nasty visible crosshatching. Seven anyway.', '2010-11-07 19:01:15.000000', NULL, 1),
(6215220, 913291, 76335, '<td valign="top">What? No pretty colors? This is the nasty truth behind it all. Great.</td>', 'What? No pretty colors? This is the nasty truth behind it all. Great.', '2010-11-07 19:01:17.000000', NULL, 1),
(6215221, 916378, 76335, '<td valign="top">I almost blew past this in voting. It''s subtle. I like the impressionistic patterns in the water juxtaposed against the foreground bank and rocks. Nice.</td>', 'I almost blew past this in voting. It''s subtle. I like the impressionistic patterns in the water juxtaposed against the foreground bank and rocks. Nice.', '2010-11-07 19:01:20.000000', NULL, 1),
(6215223, 912972, 76335, '<td valign="top">Good Lord, that''s terrifying! And most excellent.</td>', 'Good Lord, that''s terrifying! And most excellent.', '2010-11-07 19:01:34.000000', NULL, 1),
(6215225, 916508, 76335, '<td valign="top">Upper right -- almost looks like a face looking down. Good to see something a little different from the northern latitudes.</td>', 'Upper right -- almost looks like a face looking down. Good to see something a little different from the northern latitudes.', '2010-11-07 19:01:40.000000', NULL, 1),
(6215227, 914139, 76335, '<td valign="top">I love the swirling background that seems to echo both her sweater and carefree expression. The blown highlights are little ditracting -- but only because I''m used to looking for such things. <br/> <br/>Really nice.</td>', 'I love the swirling background that seems to echo both her sweater and carefree expression. The blown highlights are little ditracting -- but only because I''m used to looking for such things.  Really nice.', '2010-11-07 19:01:45.000000', NULL, 1),
(6215228, 916679, 76335, '<td valign="top">I love the composition. The tilt, the layering -- all very effective. Good earthy textures too.</td>', 'I love the composition. The tilt, the layering -- all very effective. Good earthy textures too.', '2010-11-07 19:01:48.000000', NULL, 1),
(6215229, 916539, 76335, '<td valign="top">International. Cosmopolitan. Technically very good.</td>', 'International. Cosmopolitan. Technically very good.', '2010-11-07 19:01:50.000000', NULL, 1),
(6215230, 914629, 76335, '<td valign="top">Fantastic composition. I might have been tempted to do this in black and white. But the color here is sublime.</td>', 'Fantastic composition. I might have been tempted to do this in black and white. But the color here is sublime.', '2010-11-07 19:01:52.000000', NULL, 1),
(6215231, 913371, 76335, '<td valign="top">Very fragile, beautiful. The bokeh almost steals the show. Almost.</td>', 'Very fragile, beautiful. The bokeh almost steals the show. Almost.', '2010-11-07 19:01:53.000000', NULL, 1),
(6215232, 917416, 76335, '<td valign="top">Fabulous use of color. Really pops. Very expert work here.</td>', 'Fabulous use of color. Really pops. Very expert work here.', '2010-11-07 19:01:55.000000', NULL, 1),
(6215234, 917326, 76335, '<td valign="top">Dazzling colors and texture so sharp they seem real. Beautiful.</td>', 'Dazzling colors and texture so sharp they seem real. Beautiful.', '2010-11-07 19:02:01.000000', NULL, 1),
(6215235, 916626, 76335, '<td valign="top">Simply splendid. The framing is perfect. Says so much about the place.</td>', 'Simply splendid. The framing is perfect. Says so much about the place.', '2010-11-07 19:02:03.000000', NULL, 1),
(6215236, 916779, 76335, '<td valign="top">Someone carved a nice face on to that one. Cute.</td>', 'Someone carved a nice face on to that one. Cute.', '2010-11-07 19:02:06.000000', NULL, 1),
(6215237, 917398, 76335, '<td valign="top">Beautiful. Dark, but nothing is lost in the shadows. I think I can hear the river...</td>', 'Beautiful. Dark, but nothing is lost in the shadows. I think I can hear the river...', '2010-11-07 19:02:09.000000', NULL, 1),
(6215239, 917264, 76335, '<td valign="top">Oh, dear. She''s leaving the frame. You''ve broken the first and last rule of photography. Extra points for breaking rules.</td>', 'Oh, dear. She''s leaving the frame. You''ve broken the first and last rule of photography. Extra points for breaking rules.', '2010-11-07 19:02:14.000000', NULL, 1),
(6215240, 916784, 76335, '<td valign="top">Beautful abstract from nature. The exposure is perfect.</td>', 'Beautful abstract from nature. The exposure is perfect.', '2010-11-07 19:02:51.000000', NULL, 1),
(6215241, 916437, 76335, '<td valign="top">Fabulous use of DOF. Brings new magic to a very familiar scene. Feels like they''re floating, racing toward me...</td>', 'Fabulous use of DOF. Brings new magic to a very familiar scene. Feels like they''re floating, racing toward me...', '2010-11-07 19:02:55.000000', NULL, 1),
(6215242, 917255, 76335, '<td valign="top">Beautifully composed.</td>', 'Beautifully composed.', '2010-11-07 19:02:56.000000', NULL, 1),
(6215244, 917073, 115307, '<td valign="top">My initial reaction to this was immediate dislike, as my mouse wandered closer to the low numbers.<br/>But then the image grabbed me. This is really powerful. I can''t look away from those eyes.<br/>I suspect this isn''t doing to well, as it doesn''t match was dpc likes, but this image is definitely worth a second look. It needs some time to be appreciated. 7</td>', 'My initial reaction to this was immediate dislike, as my mouse wandered closer to the low numbers.But then the image grabbed me. This is really powerful. I can''t look away from those eyes.I suspect this isn''t doing to well, as it doesn''t match was dpc likes, but this image is definitely worth a second look. It needs some time to be appreciated. 7', '2010-11-07 19:03:02.000000', NULL, 1),
(6215245, 917049, 76335, '<td valign="top">Lots to take in here. Very intriguing.</td>', 'Lots to take in here. Very intriguing.', '2010-11-07 19:03:02.000000', NULL, 1),
(6215246, 915616, 76335, '<td valign="top">This was a wonderful find. The light looks like it was agreeable and you''ve captured the scene to perfection. Great subject isolation with the dark background bokeh.</td>', 'This was a wonderful find. The light looks like it was agreeable and you''ve captured the scene to perfection. Great subject isolation with the dark background bokeh.', '2010-11-07 19:03:05.000000', NULL, 1),
(6215247, 916954, 76335, '<td valign="top">Beautiful, beautiful. Fantastic eye to see this.</td>', 'Beautiful, beautiful. Fantastic eye to see this.', '2010-11-07 19:03:08.000000', NULL, 1),
(6215249, 917401, 76335, '<td valign="top">Beautiful light. Wonderful textures. Excellent.</td>', 'Beautiful light. Wonderful textures. Excellent.', '2010-11-07 19:03:14.000000', NULL, 1),
(6215250, 917449, 76335, '<td valign="top">Beautiful movement. A dance in mid air. Pure poetry.</td>', 'Beautiful movement. A dance in mid air. Pure poetry.', '2010-11-07 19:03:50.000000', NULL, 1),
(6215251, 916033, 76335, '<td valign="top">To rate this as a photograph would be to miss the point. Honestly, what could I say? "Needs more DOF." "Nice capture!" This is art of the highest order. Brilliant.</td>', 'To rate this as a photograph would be to miss the point. Honestly, what could I say? "Needs more DOF." "Nice capture!" This is art of the highest order. Brilliant.', '2010-11-07 19:03:54.000000', NULL, 1),
(6215252, 916810, 76335, '<td valign="top">The zone plate takes on suburbia? I like this a lot. But I like rectangles.</td>', 'The zone plate takes on suburbia? I like this a lot. But I like rectangles.', '2010-11-07 19:03:56.000000', NULL, 1),
(6215253, 917170, 76335, '<td valign="top">Feels very <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=13688" rel="nofollow" target="_blank">muur88</a>. I love all the movement and the feeling of imminent collision.</td>', 'Feels very  muur88. I love all the movement and the feeling of imminent collision.', '2010-11-07 19:03:58.000000', NULL, 1),
(6215254, 917277, 76335, '<td valign="top">I love their choreography. The slow shutter preserves some of the dance for the viewer. Beautiful.</td>', 'I love their choreography. The slow shutter preserves some of the dance for the viewer. Beautiful.', '2010-11-07 19:04:00.000000', NULL, 1),
(6215255, 917464, 76335, '<td valign="top">Good use of time travel. Love this.</td>', 'Good use of time travel. Love this.', '2010-11-07 19:04:03.000000', NULL, 1),
(6215256, 916608, 76335, '<td valign="top">Evocative of an alien world. Wonderful.</td>', 'Evocative of an alien world. Wonderful.', '2010-11-07 19:04:05.000000', NULL, 1),
(6215257, 917336, 76335, '<td valign="top">Beautiful black and white landscape.</td>', 'Beautiful black and white landscape.', '2010-11-07 19:04:07.000000', NULL, 1),
(6215258, 915810, 76335, '<td valign="top">Magical. I love it.</td>', 'Magical. I love it.', '2010-11-07 19:04:11.000000', NULL, 1),
(6215259, 914323, 76335, '<td valign="top">Great! Almost looks like the child is thinking or dreaming -- or remembering this.</td>', 'Great! Almost looks like the child is thinking or dreaming -- or remembering this.', '2010-11-07 19:04:14.000000', NULL, 1),
(6215260, 914800, 76335, '<td valign="top">Is this infrared? Really nice -- especially in black and white.</td>', 'Is this infrared? Really nice -- especially in black and white.', '2010-11-07 19:04:16.000000', NULL, 1),
(6215261, 916888, 76335, '<td valign="top">Yes -- my kind of air show. Love your two "spectators."</td>', 'Yes -- my kind of air show. Love your two "spectators."', '2010-11-07 19:04:17.000000', NULL, 1),
(6215262, 917342, 115307, '<td valign="top">I really like the lines and symmetry of this image, but the man needs to be a lot sharper in order to be truly effective. The blurriness takes away most of the impact that this image could have.  I suggest you go reshoot this. There is definitely something interesting here. 5</td>', 'I really like the lines and symmetry of this image, but the man needs to be a lot sharper in order to be truly effective. The blurriness takes away most of the impact that this image could have.  I suggest you go reshoot this. There is definitely something interesting here. 5', '2010-11-07 19:05:03.000000', NULL, 1),
(6215263, 914672, 76335, '<td valign="top">Excellent on so many levels. Must be a great story here. Looks like the child had been crying but has managed a smile now. The warm colors and framing work well too.</td>', 'Excellent on so many levels. Must be a great story here. Looks like the child had been crying but has managed a smile now. The warm colors and framing work well too.', '2010-11-07 19:05:34.000000', NULL, 1),
(6215266, 917313, 115307, '<td valign="top">Lovely place, but the image comes off overall as far too bright. I wouldn''t go so far too say overexposed, as you kept the details in the mountain. But it is still quite...glaring.</td>', 'Lovely place, but the image comes off overall as far too bright. I wouldn''t go so far too say overexposed, as you kept the details in the mountain. But it is still quite...glaring.', '2010-11-07 19:08:15.000000', NULL, 1),
(6215271, 917277, 30982, '<td valign="top">Won''t let me fav it twice, darn it.</td>', 'Won''t let me fav it twice, darn it.', '2010-11-07 19:12:31.000000', NULL, 1),
(6215273, 915636, 115307, '<td valign="top">Great processing! Almost feels like a drawing to me, and the powerful black and white really gives the castle a looming feel. I don''t really like the slanted tower in the top right corner, but agree that the right boulder needed to be included composition wise, so I don''t know how that could have been fixed. Great shot! 9</td>', 'Great processing! Almost feels like a drawing to me, and the powerful black and white really gives the castle a looming feel. I don''t really like the slanted tower in the top right corner, but agree that the right boulder needed to be included composition wise, so I don''t know how that could have been fixed. Great shot! 9', '2010-11-07 19:12:43.000000', NULL, 1),
(6215278, 914915, 30982, '<td valign="top">Very much my kind of shot.  Lovely.</td>', 'Very much my kind of shot.  Lovely.', '2010-11-07 19:13:33.000000', NULL, 1),
(6215279, 916772, 65234, '<td valign="top">Love the composition with the surfer on a diagonal, and the wave is beautifully captured.</td>', 'Love the composition with the surfer on a diagonal, and the wave is beautifully captured.', '2010-11-07 19:13:37.000000', NULL, 1),
(6215280, 916112, 30982, '<td valign="top">Breathtakingly powerful.</td>', 'Breathtakingly powerful.', '2010-11-07 19:14:06.000000', NULL, 1),
(6215281, 917467, 65234, '<td valign="top">Lighting seems a bit flat.</td>', 'Lighting seems a bit flat.', '2010-11-07 19:14:39.000000', NULL, 1),
(6215282, 917001, 30982, '<td valign="top">Excellent low key work!</td>', 'Excellent low key work!', '2010-11-07 19:14:44.000000', NULL, 1),
(6215283, 917452, 30982, '<td valign="top">Has a Neil Shapiro feel to it.  Beautifully done.</td>', 'Has a Neil Shapiro feel to it.  Beautifully done.', '2010-11-07 19:15:25.000000', NULL, 1),
(6215284, 916953, 30982, '<td valign="top">Quite a magnificent view - beautifully captured and I really enjoy it in B&amp;W.</td>', 'Quite a magnificent view - beautifully captured and I really enjoy it in B&W.', '2010-11-07 19:15:46.000000', NULL, 1),
(6215285, 916819, 50695, '<td valign="top">beautiful, supple, with hidden faces, hidden stories, and missing faces, missing stories.<br/> <br/>Posthumous Art Gallery</td>', 'beautiful, supple, with hidden faces, hidden stories, and missing faces, missing stories. Posthumous Art Gallery', '2010-11-07 19:18:12.000000', NULL, 1),
(6215286, 915382, 50695, '<td valign="top">Remarkably infinite.<br/> <br/>Posthumous Art Gallery</td>', 'Remarkably infinite. Posthumous Art Gallery', '2010-11-07 19:18:42.000000', NULL, 1),
(6215287, 917248, 65234, '<td valign="top">I was there!  Lots of entertaining signs there.  This is not the most clever one I''ve seen but the smile looks genuinely happy and the hair is ... colorful ;-)  This being Advanced editing I might have burnt/cloned to get rid of the blur on her jacket (I''m guessing it''s someone''s OOF head but it''s too amorphous to add "crowd" context to the shot).</td>', 'I was there!  Lots of entertaining signs there.  This is not the most clever one I''ve seen but the smile looks genuinely happy and the hair is ... colorful ;-)  This being Advanced editing I might have burnt/cloned to get rid of the blur on her jacket (I''m guessing it''s someone''s OOF head but it''s too amorphous to add "crowd" context to the shot).', '2010-11-07 19:18:48.000000', NULL, 1),
(6215288, 917264, 67697, '<td valign="top">I don''t get the title but I really like the scene.  Makes you wonder what catches her interest here.</td>', 'I don''t get the title but I really like the scene.  Makes you wonder what catches her interest here.', '2010-11-07 19:19:24.000000', NULL, 1),
(6215289, 917110, 65234, '<td valign="top">Great sense of movement in this one.</td>', 'Great sense of movement in this one.', '2010-11-07 19:19:27.000000', NULL, 1),
(6215290, 913895, 67697, '<td valign="top">love the lighting.</td>', 'love the lighting.', '2010-11-07 19:19:39.000000', NULL, 1),
(6215292, 917064, 30982, '<td valign="top">This one really draws me in for reasons I can''t quite explain.</td>', 'This one really draws me in for reasons I can''t quite explain.', '2010-11-07 19:19:52.000000', NULL, 1),
(6215293, 917487, 67697, '<td valign="top">very dreamy.  love the light in the mist.</td>', 'very dreamy.  love the light in the mist.', '2010-11-07 19:19:59.000000', NULL, 1),
(6215294, 914323, 67697, '<td valign="top">I like the composition.  Interesting use of DOF.</td>', 'I like the composition.  Interesting use of DOF.', '2010-11-07 19:20:30.000000', NULL, 1),
(6215296, 917243, 65234, '<td valign="top">I like the sharp, clear lines on the road disappearing into the soft vagaries of the unknown beyond.</td>', 'I like the sharp, clear lines on the road disappearing into the soft vagaries of the unknown beyond.', '2010-11-07 19:21:40.000000', NULL, 1),
(6215298, 915616, 67697, '<td valign="top">I like how you used the darkness to separate the background from your subject.  In the first go around I missed that this is actually a feather in the scene.  Glad I stopped to comment.</td>', 'I like how you used the darkness to separate the background from your subject.  In the first go around I missed that this is actually a feather in the scene.  Glad I stopped to comment.', '2010-11-07 19:21:54.000000', NULL, 1),
(6215302, 917416, 65234, '<td valign="top">Nice light and detail.  Like the buds and flower in various stages of development; tells a story.</td>', 'Nice light and detail.  Like the buds and flower in various stages of development; tells a story.', '2010-11-07 19:23:07.000000', NULL, 1);
