(6215315, 917464, 50695, '<td valign="top">I love the nostalgia that soaks this photo to the point of unreality.<br/> <br/>Posthumous Art Gallery</td>', 'I love the nostalgia that soaks this photo to the point of unreality. Posthumous Art Gallery', '2010-11-07 19:26:16.000000', NULL, 1),
